param([string]$EnvFile = ".env")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop";$repoRoot=Split-Path -Parent $PSScriptRoot;$envPath=if([IO.Path]::IsPathRooted($EnvFile)){$EnvFile}else{Join-Path $repoRoot $EnvFile};$remoteRoot="/home/testpilot/mim";$portalBefore="606d6a52daeaa6e03c0f99e2a20dbe703bdc12c2928cff946c1e10e606f0fa79";$portalAfter="db1eb8e7127d22402793be067e72ec7208a24f61f9ddf65aa552e0027d51017f";$configBefore="9b3c32196cd1a668f6810762734101feb85a544b7babcf03b9dc6bf2ea7a8a21";$configAfter="66e5ce1a1a067d8ffee71967c5536832ac62a19ee26972b0238305b451fecaf3"
function Get-EnvValue {param([string]$Name)$line=Get-Content -LiteralPath $envPath|Where-Object{$_ -match ("^\s*{0}\s*=" -f [regex]::Escape($Name))}|Select-Object -First 1;if(-not $line){return ""};return(($line -replace ("^\s*{0}\s*=\s*" -f [regex]::Escape($Name)),"").Trim().Trim('"'))}
function Invoke-RemoteChecked {param([int]$SessionId,[string]$Command,[int]$TimeoutSeconds=120)$r=Invoke-SSHCommand -SessionId $SessionId -Command $Command -TimeOut $TimeoutSeconds;if($r.ExitStatus -ne 0){throw "Remote command failed $($r.ExitStatus): output=$($r.Output -join ' | ') error=$($r.Error -join '; ')"};return $r}
function Send-RemoteFileB64 {param([int]$SessionId,[string]$LocalPath,[string]$RemotePath)$full=(Resolve-Path(Join-Path $repoRoot $LocalPath)).Path;$encoded=[Convert]::ToBase64String([IO.File]::ReadAllBytes($full));$tmp="/tmp/codex_google_identity_$([Guid]::NewGuid().ToString('N')).b64";for($o=0;$o-lt$encoded.Length;$o+=12000){$c=$encoded.Substring($o,[Math]::Min(12000,$encoded.Length-$o));Invoke-RemoteChecked $SessionId "printf '%s' '$c' >> '$tmp'"|Out-Null};Invoke-RemoteChecked $SessionId "base64 -d '$tmp' > '$RemotePath' && rm -f '$tmp'"|Out-Null}
Import-Module Posh-SSH -ErrorAction Stop;$credential=[pscredential]::new((Get-EnvValue "MIM_SSH_USER"),(ConvertTo-SecureString (Get-EnvValue "MIM_SSH_PASSWORD") -AsPlainText -Force));$pt=Get-EnvValue "MIM_SSH_PORT";$port=if($pt){[int]$pt}else{22};$session=New-SSHSession -ComputerName (Get-EnvValue "MIM_SSH_HOST") -Port $port -Credential $credential -AcceptKey -Force
try{$portalCandidate="$remoteRoot/scripts/project_portal_google_identity_candidate.py";Send-RemoteFileB64 $session.SessionId "tmp_remote_mim/core/routers/project_portal.py" $portalCandidate;Send-RemoteFileB64 $session.SessionId "runtime_remote_training/remote_scripts/apply_google_identity_config_v1.py" "$remoteRoot/scripts/apply_google_identity_config_v1.py";Send-RemoteFileB64 $session.SessionId "runtime_remote_training/remote_scripts/validate_google_identity_v1.py" "$remoteRoot/scripts/validate_google_identity_v1.py";$portalCurrent=([string]((Invoke-RemoteChecked $session.SessionId "sha256sum '$remoteRoot/core/routers/project_portal.py' | awk '{print `$1}'").Output|Select-Object -First 1)).Trim();$configCurrent=([string]((Invoke-RemoteChecked $session.SessionId "sha256sum '$remoteRoot/core/config.py' | awk '{print `$1}'").Output|Select-Object -First 1)).Trim();$candidateHash=([string]((Invoke-RemoteChecked $session.SessionId "sha256sum '$portalCandidate' | awk '{print `$1}'").Output|Select-Object -First 1)).Trim();if($candidateHash -ne $portalAfter){throw "Portal candidate hash mismatch $candidateHash"};if($configCurrent -eq $configBefore){(Invoke-RemoteChecked $session.SessionId "cd '$remoteRoot' && .venv/bin/python scripts/apply_google_identity_config_v1.py").Output}elseif($configCurrent -ne $configAfter){throw "Unexpected config hash $configCurrent"};(Invoke-RemoteChecked $session.SessionId "cd '$remoteRoot' && .venv/bin/python -m py_compile core/config.py '$portalCandidate'").Output;if($portalCurrent -eq $portalBefore){$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ');$backup="$remoteRoot/core/routers/project_portal.py.bak.google-identity.$stamp";(Invoke-RemoteChecked $session.SessionId "cp '$remoteRoot/core/routers/project_portal.py' '$backup' && cp '$portalCandidate' '$remoteRoot/core/routers/project_portal.py'").Output;"rollback=$backup"}elseif($portalCurrent -ne $portalAfter){throw "Unexpected portal hash $portalCurrent"};(Invoke-RemoteChecked $session.SessionId "cd '$remoteRoot' && .venv/bin/python -m py_compile core/config.py core/routers/project_portal.py").Output;(Invoke-RemoteChecked $session.SessionId "systemctl --user restart mim-mobile-web.service mim-training-web.service && sleep 2 && systemctl --user is-active mim-mobile-web.service mim-training-web.service").Output;(Invoke-RemoteChecked $session.SessionId "cd '$remoteRoot' && PYTHONPATH='$remoteRoot' MIM_ROOT='$remoteRoot' .venv/bin/python scripts/validate_google_identity_v1.py").Output;(Invoke-RemoteChecked $session.SessionId "curl -sS -o /dev/null -D - 'https://mim.mimtod.com/auth/google/start' | head -n 8").Output;(Invoke-RemoteChecked $session.SessionId "sha256sum '$remoteRoot/core/routers/project_portal.py' '$remoteRoot/core/config.py'").Output}finally{if($session){Remove-SSHSession -SessionId $session.SessionId|Out-Null}}
